const b = $json.body || {};
const name = b.name || 'there';
const status = (b.status || '').toLowerCase();
let subject, intro, detail;
if (status === 'revoked') {
  subject = 'H!RE — Your company account has been revoked';
  intro = 'has been revoked';
  detail = (b.reason ? ('Reason: ' + b.reason + ' ') : '') + 'Your account access has been suspended. To restore your account, please contact the H!RE Admins at hiree.noreply@gmail.com.';
} else if (status === 'restored') {
  subject = 'H!RE — Your company account has been restored';
  intro = 'has been restored';
  detail = 'Your account is active again and you can log in as usual. Welcome back!';
} else {
  subject = 'H!RE — Your company account has been deleted';
  intro = 'has been permanently deleted';
  detail = 'This action is permanent and your account can no longer be restored. If you have questions, contact hiree.noreply@gmail.com.';
}
const html = `<div style="font-family: Arial, sans-serif; max-width:600px; margin:0 auto; color:#0d1b3e;">
  <h2 style="color:#f97316;">Company Account Update</h2>
  <p>Hi ${name},</p>
  <p>Your H!RE company account <strong>${name}</strong> ${intro}.</p>
  <div style="background:#f1f5f9; border-radius:8px; padding:16px; margin:16px 0;">${detail}</div>
  <br/>
  <p>Best regards,<br/><strong>The H!RE Team</strong></p>
</div>`;
return [{ json: { sendTo: b.email, subject, html } }];
